Question 4
a)(i) SELECT O.OID, C.name FROM "Order" O, Customer C WHERE O.CID = C.CID AND C.gender = 'F' AND C.address LIKE '%France%'; a)(i) SELECT OID, name FROM Order, Customer WHERE gender = 'F' AND address LIKE '%France%';
a)(ii) SELECT CID FROM Customer WHERE CID NOT IN (SELECT O.CID FROM "Order" O, OrderItems OI, Product P, Manufacturer M WHERE O.OID = OI.OID AND OI.PID = P.PID AND P.MID = M.MID AND P.name = 'phones' AND M.country = 'India');
a)(iii) SELECT C.name, C.creditLimit FROM Customer C JOIN "Order" O ON C.CID = O.CID JOIN (SELECT OID, SUM(qty) AS total FROM OrderItems GROUP BY OID HAVING SUM(qty) > 10) T ON O.OID = T.OID; a)(iii) The subquery aggregates the quantities per order and keeps only the orders above the threshold with HAVING, because the condition applies to the group and not to a single row. SUM must be repeated in HAVING since the alias cannot be used there in standard SQL.
b) CREATE FUNCTION dbo.TotalPrice(@OID char(10)) RETURNS int AS BEGIN RETURN (SELECT SUM(P.unitPrice * OI.qty) FROM OrderItems OI, Product P WHERE OI.PID = P.PID AND OI.OID = @OID); END;
c) CREATE TRIGGER trgPackageWeight ON OrderItems AFTER INSERT AS BEGIN IF (SELECT SUM(P.weight * OI.qty) FROM inserted OI JOIN Product P ON OI.PID = P.PID) > 2000 RAISERROR('Too heavy', 16, 1); ROLLBACK TRANSACTION; END;

